INSERT INTO `hazard_events`
  (`code`,`context`,`category`,`name_es`,`name_en`,`description_es`,`description_en`,`control_measure_es`,`control_measure_en`,`default_likelihood`,`default_consequence`,`sort_order`,`is_active`)
VALUES
  ('ADP-001','set_build','heights','Trabajo en la parrilla del foro sin arnés ni línea de vida','Work on the stage grid without harness or lifeline','Personal circulando y montando luminarias sobre la parrilla/grid del foro sin arnés de cuerpo entero ni línea de vida anclada.','Crew moving and rigging lights on the stage grid without a full-body harness or anchored lifeline.','Uso estricto de sistema personal de detención de caídas (arnés, línea de vida) a más de 1.8m. Barandales perimetrales. Inspección diaria de equipos de elevación, arneses y anclajes (NOM-009-STPS). Safety bonds obligatorios en equipo suspendido.','Strict use of personal fall arrest systems (harness, lifeline) above 1.8m (6ft). Perimeter guardrails. Daily inspection of lifting equipment, harnesses, and anchor points. Mandatory safety bonds on suspended equipment.','C',5,77,1),
  ('ADP-002','set_build','heights','Caída de herramienta u objeto desde la parrilla sobre el personal','Tool or object falling from the grid onto crew below','Herramientas, tornillería o accesorios sin amarre que caen desde la parrilla golpeando a quien trabaja en el piso del foro.','Untethered tools, hardware or fittings dropping from the grid and striking crew on the stage floor.','Uso estricto de sistema personal de detención de caídas (arnés, línea de vida) a más de 1.8m. Barandales perimetrales. Inspección diaria de equipos de elevación, arneses y anclajes (NOM-009-STPS). Safety bonds obligatorios en equipo suspendido.','Strict use of personal fall arrest systems (harness, lifeline) above 1.8m (6ft). Perimeter guardrails. Daily inspection of lifting equipment, harnesses, and anchor points. Mandatory safety bonds on suspended equipment.','C',4,78,1),
  ('ADP-003','set_build','heights','Luminaria o accesorio colgado sin cable de seguridad secundario','Fixture hung without a secondary safety cable','Luminaria, truss o accesorio colgado del grid sin cable de seguridad (safety) redundante que lo retenga si falla el gancho o la abrazadera.','Light, truss or accessory hung from the grid without a redundant safety cable to catch it if the hook or clamp fails.','Uso estricto de sistema personal de detención de caídas (arnés, línea de vida) a más de 1.8m. Barandales perimetrales. Inspección diaria de equipos de elevación, arneses y anclajes (NOM-009-STPS). Safety bonds obligatorios en equipo suspendido.','Strict use of personal fall arrest systems (harness, lifeline) above 1.8m (6ft). Perimeter guardrails. Daily inspection of lifting equipment, harnesses, and anchor points. Mandatory safety bonds on suspended equipment.','C',4,79,1),
  ('ADP-004','set_build','heights','Uso de plataforma tijera o articulada en foro sin estabilización ni cinturón','Scissor or boom lift used on stage without stabilization or restraint','Operación de scissor/boom lift para montaje en foro sin estabilizadores, sin cinturón de posición ni control de piso nivelado.','Operating a scissor/boom lift for stage rigging without outriggers, restraint lanyard or a level floor check.','Uso estricto de sistema personal de detención de caídas (arnés, línea de vida) a más de 1.8m. Barandales perimetrales. Inspección diaria de equipos de elevación, arneses y anclajes (NOM-009-STPS). Safety bonds obligatorios en equipo suspendido.','Strict use of personal fall arrest systems (harness, lifeline) above 1.8m (6ft). Perimeter guardrails. Daily inspection of lifting equipment, harnesses, and anchor points. Mandatory safety bonds on suspended equipment.','C',4,80,1),
  ('ADP-005','set_build','heights','Andamio o torre rodante mal armado o sin barandal durante el montaje','Scaffold or rolling tower poorly assembled or without guardrail during build','Montaje de escenografía desde andamio o torre rodante incompleto, sin arriostre, sin barandal ni tablones asegurados.','Building set pieces from a scaffold or rolling tower that is incomplete, unbraced, lacks guardrails or has unsecured planks.','Uso estricto de sistema personal de detención de caídas (arnés, línea de vida) a más de 1.8m. Barandales perimetrales. Inspección diaria de equipos de elevación, arneses y anclajes (NOM-009-STPS). Safety bonds obligatorios en equipo suspendido.','Strict use of personal fall arrest systems (harness, lifeline) above 1.8m (6ft). Perimeter guardrails. Daily inspection of lifting equipment, harnesses, and anchor points. Mandatory safety bonds on suspended equipment.','C',4,81,1),
  ('ADP-006','set_build','heights','Caída desde escalera de mano al vestir el set en altura media','Fall from a portable ladder while dressing the set at mid height','Uso de escalera de mano inestable o mal apoyada durante el set-dressing, con riesgo de caída al sobreextenderse o perder equilibrio.','Using an unstable or poorly footed portable ladder during set dressing, risking a fall from overreaching or loss of balance.','Uso estricto de sistema personal de detención de caídas (arnés, línea de vida) a más de 1.8m. Barandales perimetrales. Inspección diaria de equipos de elevación, arneses y anclajes (NOM-009-STPS). Safety bonds obligatorios en equipo suspendido.','Strict use of personal fall arrest systems (harness, lifeline) above 1.8m (6ft). Perimeter guardrails. Daily inspection of lifting equipment, harnesses, and anchor points. Mandatory safety bonds on suspended equipment.','B',3,82,1),
  ('ADP-007','set_build','heights','Carga suspendida en rigging sobre personas sin zona despejada','Suspended rigging load over people without a cleared exclusion zone','Izaje de truss, tarima volada o pieza de escenografía por encima del personal sin acordonar ni despejar la zona bajo la carga.','Hoisting truss, a flown platform or a set piece over crew without cordoning off or clearing the area beneath the load.','Uso estricto de sistema personal de detención de caídas (arnés, línea de vida) a más de 1.8m. Barandales perimetrales. Inspección diaria de equipos de elevación, arneses y anclajes (NOM-009-STPS). Safety bonds obligatorios en equipo suspendido.','Strict use of personal fall arrest systems (harness, lifeline) above 1.8m (6ft). Perimeter guardrails. Daily inspection of lifting equipment, harnesses, and anchor points. Mandatory safety bonds on suspended equipment.','C',5,83,1),
  ('ADP-008','set_build','electrical','Contacto con distribución eléctrica temporal de foro energizada o dañada','Contact with energized or damaged temporary stage power distribution','Contacto con feeders, tableros o conexiones de la distribución eléctrica temporal del foro con aislamiento dañado o conductores expuestos.','Contact with temporary stage power feeders, panels or connections that have damaged insulation or exposed conductors.','Inspección previa por eléctrico calificado. Asegurar conexiones y tableros. Uso de EPP dieléctrico, procedimiento LOTO (NOM-029-STPS), ruteo seguro de cableado, pasacables, y protección diferencial (GFCI/RCD).','Pre-inspection by a qualified electrician. Secure connections/panels. Use of dielectric PPE, LOTO procedure (OSHA), safe cable routing, cable crossovers, and GFCI/RCD protection.','C',5,84,1),
  ('ADP-009','set_build','electrical','Distribución eléctrica temporal en piso mojado o junto al tanque','Temporary power distribution on wet floor or beside the water tank','Conexiones y feeders de energía temporal tendidos sobre piso mojado, cerca del tanque o de labores de limpieza, con riesgo de electrocución.','Temporary power connections and feeders run over a wet floor, near the tank or cleaning work, creating an electrocution risk.','Inspección previa por eléctrico calificado. Asegurar conexiones y tableros. Uso de EPP dieléctrico, procedimiento LOTO (NOM-029-STPS), ruteo seguro de cableado, pasacables, y protección diferencial (GFCI/RCD).','Pre-inspection by a qualified electrician. Secure connections/panels. Use of dielectric PPE, LOTO procedure (OSHA), safe cable routing, cable crossovers, and GFCI/RCD protection.','C',5,85,1),
  ('ADP-010','set_build','electrical','Intervención de tableros o feeders sin bloqueo y etiquetado (LOTO)','Working on panels or feeders without lockout/tagout (LOTO)','Reconexión o mantenimiento de tableros y feeders durante el montaje sin aplicar bloqueo/etiquetado que garantice la desenergización.','Reconnecting or servicing panels and feeders during the build without applying lockout/tagout to guarantee de-energization.','Inspección previa por eléctrico calificado. Asegurar conexiones y tableros. Uso de EPP dieléctrico, procedimiento LOTO (NOM-029-STPS), ruteo seguro de cableado, pasacables, y protección diferencial (GFCI/RCD).','Pre-inspection by a qualified electrician. Secure connections/panels. Use of dielectric PPE, LOTO procedure (OSHA), safe cable routing, cable crossovers, and GFCI/RCD protection.','C',5,86,1),
  ('ADP-011','set_build','access','Cables y feeders tendidos en accesos y pasillos sin protección (tropiezo)','Cables and feeders across access routes without protection (trip hazard)','Feeders y cableado tendidos por pasillos y accesos del foro sin canaleta ni puente de cable, generando riesgo de tropiezo y caída.','Feeders and cabling laid across stage aisles and access routes without cable ramps or bridges, creating a trip-and-fall hazard.','Garantizar al menos dos vías de evacuación libres de obstáculos y bien señalizadas. Validar acceso para ambulancias y vehículos de emergencia; mantener áreas de paso libres de equipo (NOM-002-STPS).','Ensure at least two obstacle-free and well-marked evacuation routes. Validate access for ambulances/emergency vehicles; keep walkways clear of equipment.','B',3,87,1),
  ('ADP-012','set_build','traffic','Montacargas maniobrando escenografía en foro con peatones alrededor','Forklift moving set pieces on stage with pedestrians nearby','Montacargas trasladando tarimas y escenografía dentro del foro sin rutas separadas ni señalero, con personal a pie en la trayectoria.','A forklift moving platforms and set pieces inside the stage without separated routes or a spotter, with crew on foot in its path.','Cierre total o parcial de calles con autoridades (Policía/Tránsito). Escolta policial. Uso de cinturones/arneses dentro de vehículos. Perímetro de seguridad. Prohibición de viajar en bateas o exterior sin rigging certificado.','Full/partial street closures with local authorities (Police/Traffic). Police escort. Use of seatbelts/harnesses inside vehicles. Safety perimeter. Prohibition of riding in truck beds or exterior without certified rigging.','C',4,88,1),
  ('ADP-013','set_build','structural','Estibado inestable de paneles y escenografía con riesgo de colapso','Unstable stacking of panels and set pieces liable to collapse','Paneles, tarimas y piezas de escenografía apilados de forma inestable o a exceso de altura que pueden volcarse sobre el personal.','Panels, platforms and set pieces stacked unstably or too high, liable to topple onto crew.','Evaluación estructural por perito (DRO) o ingeniero calificado. Apuntalamiento preventivo. Restricción de carga viva en la zona. Monitoreo constante de vibraciones o asentamientos.','Structural evaluation by a qualified engineer. Preventive shoring. Live load restriction in the area. Constant monitoring of vibrations or settlement.','C',4,89,1),
  ('ADP-014','set_build','health','Sobreesfuerzo y lesión lumbar al mover cargas pesadas en el load-in','Overexertion and back injury moving heavy loads during load-in','Manejo manual de paneles, cable y escenografía pesada durante el load-in sin ayudas mecánicas ni técnica de levantamiento, causando lesión musculoesquelética.','Manual handling of panels, cable and heavy set pieces during load-in without mechanical aids or lifting technique, causing musculoskeletal injury.','Evaluación de riesgos en sitio (Risk Assessment) previa. Junta de seguridad (Safety Briefing) obligatoria. Uso de EPP básico. Delimitación y señalización del área de trabajo. Paramédico o primeros auxilios en set.','Prior on-site Risk Assessment. Mandatory Safety Briefing. Basic PPE use. Demarcation and signaling of the work area. Paramedic or first aid on set.','B',3,90,1),
  ('ADP-015','set_build','structural','Aplastamiento de manos o pies al bajar paneles pesados en el load-out','Hand or foot crush lowering heavy panels during load-out','Piezas pesadas de escenografía que atrapan manos o pies al descargarlas o bajarlas sin guantes ni calzado con casquillo durante el load-out.','Heavy set pieces catching hands or feet while unloading or lowering them without gloves or safety-toe footwear during load-out.','Evaluación de riesgos en sitio (Risk Assessment) previa. Junta de seguridad (Safety Briefing) obligatoria. Uso de EPP básico. Delimitación y señalización del área de trabajo. Paramédico o primeros auxilios en set.','Prior on-site Risk Assessment. Mandatory Safety Briefing. Basic PPE use. Demarcation and signaling of the work area. Paramedic or first aid on set.','C',3,91,1),
  ('ADP-016','set_build','confined','Trabajo bajo el escenario o foso sin permiso de espacio confinado','Work under the stage or trap room without a confined-space permit','Montaje de estructura o instalaciones bajo el escenario o en el foso sin permiso de entrada, ventilación ni monitoreo de atmósfera.','Building structure or utilities under the stage or in the trap room without an entry permit, ventilation or atmosphere monitoring.','Permiso de entrada a espacios confinados. Monitoreo de gases (O2, CO, LEL, H2S). Ventilación mecánica exhaustiva. Vigía (Hole watch) permanente en el exterior. Plan de rescate y arnés de extracción (NOM-033-STPS).','Confined space entry permit. Gas monitoring (O2, CO, LEL, H2S). Exhaustive mechanical ventilation. Permanent Hole Watch outside. Rescue plan and extraction harness.','D',5,92,1),
  ('ADP-017','set_build','confined','Ingreso al tanque de agua seco para montaje sin monitoreo de atmósfera','Entering the dry water tank to build without atmosphere monitoring','Entrada al tanque de foro vacío para montar estructura o revestimiento sin control de atmósfera, ventilación ni vigía en el exterior.','Entering the empty stage tank to build structure or lining without atmosphere control, ventilation or an outside attendant.','Permiso de entrada a espacios confinados. Monitoreo de gases (O2, CO, LEL, H2S). Ventilación mecánica exhaustiva. Vigía (Hole watch) permanente en el exterior. Plan de rescate y arnés de extracción (NOM-033-STPS).','Confined space entry permit. Gas monitoring (O2, CO, LEL, H2S). Exhaustive mechanical ventilation. Permanent Hole Watch outside. Rescue plan and extraction harness.','D',5,93,1),
  ('ADP-018','set_build','health','Exposición a ruido de maquinaria de montaje en foro cerrado','Noise exposure from build machinery inside the enclosed stage','Ruido sostenido de generadores, compresores y herramienta eléctrica de montaje dentro del foro cerrado sin protección auditiva.','Sustained noise from generators, compressors and power tools during the build inside the enclosed stage without hearing protection.','Evaluación de riesgos en sitio (Risk Assessment) previa. Junta de seguridad (Safety Briefing) obligatoria. Uso de EPP básico. Delimitación y señalización del área de trabajo. Paramédico o primeros auxilios en set.','Prior on-site Risk Assessment. Mandatory Safety Briefing. Basic PPE use. Demarcation and signaling of the work area. Paramedic or first aid on set.','B',2,94,1),
  ('ADP-019','set_build','access','Iluminación temporal deficiente durante load-in con el foro a oscuras','Poor temporary lighting during load-in with the stage in the dark','Trabajo de carga y montaje con el foro a oscuras o con iluminación provisional insuficiente, aumentando tropiezos y golpes.','Load-in and rigging work with the stage dark or with insufficient provisional lighting, increasing trips and impacts.','Garantizar al menos dos vías de evacuación libres de obstáculos y bien señalizadas. Validar acceso para ambulancias y vehículos de emergencia; mantener áreas de paso libres de equipo (NOM-002-STPS).','Ensure at least two obstacle-free and well-marked evacuation routes. Validate access for ambulances/emergency vehicles; keep walkways clear of equipment.','C',2,95,1),
  ('ADP-020','set_build','fire','Acumulación de material combustible y falta de extintores en el montaje','Combustible material buildup and lack of extinguishers during the build','Acopio de madera, foam, telas y recortes combustibles durante el montaje sin extintores accesibles ni control de carga de fuego.','Buildup of wood, foam, fabric and combustible offcuts during the build without accessible extinguishers or fire-load control.','Retirar material combustible de fuentes de ignición. Disponer de extintores PQS/CO2 tipo ABC. Inspección de calentamiento en luces. Designar fire watch en caso de flama abierta (NOM-002-STPS).','Remove combustible materials from ignition sources. Have ABC PQS/CO2 fire extinguishers on hand. Inspect lights for overheating. Assign a fire watch for open flames.','C',4,96,1),
  ('ADP-021','set_build','fire','Soldadura o corte para estructura de set sin permiso ni resguardo de incendio','Welding or cutting for set structure without a hot-work permit or fire watch','Trabajo en caliente (soldadura/corte) sobre estructura del set junto a materiales combustibles sin permiso, biombo ni vigía contra incendio.','Hot work (welding/cutting) on set structure next to combustibles without a permit, screen or fire watch.','Retirar material combustible de fuentes de ignición. Disponer de extintores PQS/CO2 tipo ABC. Inspección de calentamiento en luces. Designar fire watch en caso de flama abierta (NOM-002-STPS).','Remove combustible materials from ignition sources. Have ABC PQS/CO2 fire extinguishers on hand. Inspect lights for overheating. Assign a fire watch for open flames.','C',4,97,1),
  ('ADP-022','set_build','hazmat','Polvo de sílice y vapores de pintura o adhesivos al adaptar el set sin ventilación','Silica dust and paint or adhesive vapors adapting the set without ventilation','Generación de polvo de sílice al cortar y de vapores de pintura, solventes o adhesivos al vestir el set en foro cerrado sin ventilación ni protección respiratoria.','Silica dust from cutting and vapors from paint, solvents or adhesives while dressing the set in an enclosed stage without ventilation or respiratory protection.','Identificación y etiquetado (SGA). Hojas de datos de seguridad (HDS). Uso de EPP específico (respiradores N95/P100, Tyvek). Estaciones de lavado de ojos/duchas. Eliminación adecuada. Fumigación preventiva para biológicos (NOM-018-STPS).','Identification and labeling (GHS). Safety Data Sheets (SDS). Specific PPE (N95/P100 respirators, Tyvek). Eyewash/shower stations. Proper disposal. Preventive fumigation for biologicals.','C',3,98,1),
  ('ADP-023','set_build','access','Salidas de emergencia del foro bloqueadas por escenografía y cable','Stage emergency exits blocked by set pieces and cable','Rutas de evacuación, puertas y salidas de emergencia del foro obstruidas por escenografía, cases y feeders durante el load-in.','Evacuation routes, doors and emergency exits of the stage obstructed by set pieces, cases and feeders during load-in.','Garantizar al menos dos vías de evacuación libres de obstáculos y bien señalizadas. Validar acceso para ambulancias y vehículos de emergencia; mantener áreas de paso libres de equipo (NOM-002-STPS).','Ensure at least two obstacle-free and well-marked evacuation routes. Validate access for ambulances/emergency vehicles; keep walkways clear of equipment.','C',4,99,1),
  ('ADP-024','set_build','heights','Colgado y tensado de ciclorama o telones pesados en altura','Hanging and tensioning heavy cyclorama or drapes at height','Instalación y tensado de ciclorama, telones y bambalinas pesadas en altura, con riesgo de caída de la tela, del riel o del personal que la cuelga.','Installing and tensioning heavy cyclorama, drapes and borders at height, risking a fall of the fabric, the track or the crew hanging it.','Uso estricto de sistema personal de detención de caídas (arnés, línea de vida) a más de 1.8m. Barandales perimetrales. Inspección diaria de equipos de elevación, arneses y anclajes (NOM-009-STPS). Safety bonds obligatorios en equipo suspendido.','Strict use of personal fall arrest systems (harness, lifeline) above 1.8m (6ft). Perimeter guardrails. Daily inspection of lifting equipment, harnesses, and anchor points. Mandatory safety bonds on suspended equipment.','C',3,100,1),
  ('ART-001','transversal','health','Alergias severas a maquillaje de efectos especiales (SFX makeup/prosthetics)',NULL,NULL,NULL,'Pruebas de parche previas (patch tests). Remover inmediato al detectar irritación. Estación de lavado lista.','Prior patch tests. Immediate removal upon irritation. Eyewash station ready.',NULL,NULL,0,1),
  ('ART-002','transversal','biological','Uso de plantas venenosas o alergénicas (hiedra venenosa) para set dressing',NULL,NULL,NULL,'Sustituir por flora artificial o inocua siempre que sea posible. EPP guantes y mangas largas para Greensmen.','Substitute with artificial/harmless flora if possible. PPE gloves and long sleeves for Greensmen.',NULL,NULL,0,1),
  ('ART-003','transversal','structural','Corte o amputación por sierras en talleres de construcción de set (Mills)',NULL,NULL,NULL,'Guardas de seguridad instaladas. Botones de paro de emergencia (SawStop). Uso de empujadores, cero guantes holgados.','Safety guards installed. Emergency stop buttons (SawStop). Use of push blocks, no loose gloves.',NULL,NULL,0,1),
  ('ART-004','transversal','fire','Peligro de explosión / fuego por acumulación de aserrín o vapores en talleres',NULL,NULL,NULL,'Extracción local (Local Exhaust Ventilation). Limpieza diaria, aspiradoras HEPA, botes metálicos antichispas.','Local Exhaust Ventilation. Daily cleaning, HEPA vacuums, non-sparking metal bins.',NULL,NULL,0,1),
  ('ART-005','transversal','health','Lesiones lumbares por carga manual en departamento de Arte/Decoración',NULL,NULL,NULL,'Técnicas de levantamiento. Uso de patines, diablos o carritos. Regla de 2 personas para cargas >25kg.','Lifting techniques. Use of pallet jacks, dollies or carts. 2-person rule for loads >25kg.',NULL,NULL,0,1),
  ('CAM-001','transversal','health','Riesgos ergonómicos por operación continua de Steadicam / equipo pesado',NULL,NULL,NULL,'Pausas de descanso obligatorias. Sillas altas de descanso (apple boxes). Ejercicios de estiramiento. Asistencia de grip.','Mandatory rest breaks. High resting chairs. Stretching exercises. Grip assistance.',NULL,NULL,0,1),
  ('CAT-001','transversal','health','Intoxicación alimentaria por catering sin cadena de frío en locación remota',NULL,NULL,NULL,'Supervisión de temperaturas del catering. Higiene estricta de proveedores. Agua embotellada sellada disponible.','Catering temperature supervision. Strict vendor hygiene. Sealed bottled water available.',NULL,NULL,0,1),
  ('CON-001','construction','tools_machinery','Contacto con sierra de mesa sin guarda (retroceso o amputación)','Contact with unguarded table saw (kickback or amputation)','Corte de tableros en sierra de mesa sin guarda ni cuchilla separadora; la pieza retrocede o la mano alcanza el disco.','Ripping panels on a table saw with no blade guard or riving knife; the stock kicks back or the hand reaches the blade.','Evaluación de riesgos en sitio (Risk Assessment) previa. Junta de seguridad (Safety Briefing) obligatoria. Uso de EPP básico. Delimitación y señalización del área de trabajo. Paramédico o primeros auxilios en set.','Prior on-site Risk Assessment. Mandatory Safety Briefing. Basic PPE use. Demarcation and signaling of the work area. Paramedic or first aid on set.','B',4,55,1),
  ('CON-002','construction','tools_machinery','Retroceso (kickback) de sierra circular o ingletadora','Kickback from circular saw or miter saw','Corte con sierra circular manual o ingletadora que atasca el disco y proyecta la herramienta o la pieza contra el operador.','Cutting with a handheld circular saw or miter saw that binds the blade and throws the tool or workpiece at the operator.','Evaluación de riesgos en sitio (Risk Assessment) previa. Junta de seguridad (Safety Briefing) obligatoria. Uso de EPP básico. Delimitación y señalización del área de trabajo. Paramédico o primeros auxilios en set.','Prior on-site Risk Assessment. Mandatory Safety Briefing. Basic PPE use. Demarcation and signaling of the work area. Paramedic or first aid on set.','B',3,56,1),
  ('CON-003','construction','tools_machinery','Rotura de disco o proyección de partículas en esmeriladora angular','Disc shattering or flying particles from angle grinder','Corte o desbaste con disco abrasivo que se rompe o lanza chispas y esquirlas a ojos y cara sin careta ni gafas.','Cutting or grinding with an abrasive disc that shatters or throws sparks and shards at eyes and face without shield or goggles.','Evaluación de riesgos en sitio (Risk Assessment) previa. Junta de seguridad (Safety Briefing) obligatoria. Uso de EPP básico. Delimitación y señalización del área de trabajo. Paramédico o primeros auxilios en set.','Prior on-site Risk Assessment. Mandatory Safety Briefing. Basic PPE use. Demarcation and signaling of the work area. Paramedic or first aid on set.','B',3,57,1),
  ('CON-004','construction','tools_machinery','Disparo accidental de clavadora neumática (perforación)','Accidental pneumatic nailer discharge (puncture)','Uso de clavadora neumática en modo contacto que dispara un clavo a la mano, pierna o a un compañero cercano.','Using a pneumatic nailer in bump-fire mode that drives a nail into the hand, leg, or a nearby coworker.','Evaluación de riesgos en sitio (Risk Assessment) previa. Junta de seguridad (Safety Briefing) obligatoria. Uso de EPP básico. Delimitación y señalización del área de trabajo. Paramédico o primeros auxilios en set.','Prior on-site Risk Assessment. Mandatory Safety Briefing. Basic PPE use. Demarcation and signaling of the work area. Paramedic or first aid on set.','B',3,58,1),
  ('CON-005','construction','hazmat','Exposición a polvo de sílice al cortar MDF, tablaroca o concreto','Silica dust exposure when cutting MDF, drywall, or concrete','Corte o esmerilado en seco de materiales con sílice sin extracción ni respirador, generando polvo respirable (silicosis).','Dry cutting or grinding of silica-bearing materials without extraction or respirator, creating respirable dust (silicosis).','Identificación y etiquetado (SGA). Hojas de datos de seguridad (HDS). Uso de EPP específico (respiradores N95/P100, Tyvek). Estaciones de lavado de ojos/duchas. Eliminación adecuada. Fumigación preventiva para biológicos (NOM-018-STPS).','Identification and labeling (GHS). Safety Data Sheets (SDS). Specific PPE (N95/P100 respirators, Tyvek). Eyewash/shower stations. Proper disposal. Preventive fumigation for biologicals.','A',4,59,1),
  ('CON-006','construction','hazmat','Polvo de madera (aserrín) sin extracción ni mascarilla','Wood dust (sawdust) without extraction or mask','Lijado y corte prolongado de madera en taller sin sistema de extracción, saturando el aire de aserrín respirable.','Prolonged sanding and cutting of wood in the shop without an extraction system, saturating the air with respirable sawdust.','Identificación y etiquetado (SGA). Hojas de datos de seguridad (HDS). Uso de EPP específico (respiradores N95/P100, Tyvek). Estaciones de lavado de ojos/duchas. Eliminación adecuada. Fumigación preventiva para biológicos (NOM-018-STPS).','Identification and labeling (GHS). Safety Data Sheets (SDS). Specific PPE (N95/P100 respirators, Tyvek). Eyewash/shower stations. Proper disposal. Preventive fumigation for biologicals.','A',3,60,1),
  ('CON-007','construction','hazmat','Humos de soldadura sin ventilación (fiebre de humos metálicos)','Welding fumes without ventilation (metal fume fever)','Soldadura de estructuras de escenografía en área cerrada sin extracción localizada, inhalando humos metálicos.','Welding scenery structures in an enclosed area without local extraction, inhaling metal fumes.','Uso exclusivo de fluidos aprobados (agua/glicerina). Ventilación mecánica periódica del set. Monitoreo de calidad del aire. EPP respiratorio opcional para crew; descansos fuera del ambiente cargado.','Exclusive use of approved fluids (water/glycerin). Periodic mechanical ventilation of the set. Air quality monitoring. Optional respiratory PPE for crew; breaks outside the foggy environment.','B',3,61,1),
  ('CON-008','construction','fire','Incendio por chispas de soldadura o corte cerca de combustibles','Fire from welding or cutting sparks near combustibles','Trabajo en caliente (soldadura/corte) junto a madera, solventes o telas sin retirar combustibles ni vigía de fuego.','Hot work (welding/cutting) next to wood, solvents, or fabrics without removing combustibles or a fire watch.','Retirar material combustible de fuentes de ignición. Disponer de extintores PQS/CO2 tipo ABC. Inspección de calentamiento en luces. Designar fire watch en caso de flama abierta (NOM-002-STPS).','Remove combustible materials from ignition sources. Have ABC PQS/CO2 fire extinguishers on hand. Inspect lights for overheating. Assign a fire watch for open flames.','B',4,62,1),
  ('CON-009','construction','health','Quemadura de arco o radiación UV en soldadura (\"flash\")','Arc flash or UV radiation burn from welding','Exposición al arco de soldadura sin careta ni cortinas, causando quemadura ocular a soldador o a personal cercano.','Exposure to the welding arc without a hood or screens, causing eye burns to the welder or nearby personnel.','Evaluación de riesgos en sitio (Risk Assessment) previa. Junta de seguridad (Safety Briefing) obligatoria. Uso de EPP básico. Delimitación y señalización del área de trabajo. Paramédico o primeros auxilios en set.','Prior on-site Risk Assessment. Mandatory Safety Briefing. Basic PPE use. Demarcation and signaling of the work area. Paramedic or first aid on set.','B',2,63,1),
  ('CON-010','construction','heights','Andamio mal armado sin barandal ni rodapié al construir set alto','Poorly assembled scaffold without guardrail or toe board on a tall set','Escenografía elevada montada desde andamio sin arriostre, barandal ni tablones completos; colapso o caída del trabajador.','Tall scenery built from a scaffold lacking bracing, guardrails, or full planking; collapse or worker fall.','Uso estricto de sistema personal de detención de caídas (arnés, línea de vida) a más de 1.8m. Barandales perimetrales. Inspección diaria de equipos de elevación, arneses y anclajes (NOM-009-STPS). Safety bonds obligatorios en equipo suspendido.','Strict use of personal fall arrest systems (harness, lifeline) above 1.8m (6ft). Perimeter guardrails. Daily inspection of lifting equipment, harnesses, and anchor points. Mandatory safety bonds on suspended equipment.','B',5,64,1),
  ('CON-011','construction','heights','Caída desde escalera portátil al instalar paneles en altura','Fall from portable ladder while installing panels at height','Uso de escalera de tijera o extensión mal apoyada para fijar escenografía en altura; pérdida de equilibrio y caída.','Using an improperly footed step or extension ladder to fasten scenery at height; loss of balance and fall.','Uso estricto de sistema personal de detención de caídas (arnés, línea de vida) a más de 1.8m. Barandales perimetrales. Inspección diaria de equipos de elevación, arneses y anclajes (NOM-009-STPS). Safety bonds obligatorios en equipo suspendido.','Strict use of personal fall arrest systems (harness, lifeline) above 1.8m (6ft). Perimeter guardrails. Daily inspection of lifting equipment, harnesses, and anchor points. Mandatory safety bonds on suspended equipment.','B',4,65,1),
  ('CON-012','construction','heights','Caída por hueco o borde de plataforma sin protección en set en construcción','Fall through opening or unprotected platform edge on a set under construction','Plataforma o entarimado de escenografía con hueco o borde abierto sin barandal ni cubierta; caída a distinto nivel.','Scenery platform or decking with an open hole or unguarded edge; fall to a lower level.','Uso estricto de sistema personal de detención de caídas (arnés, línea de vida) a más de 1.8m. Barandales perimetrales. Inspección diaria de equipos de elevación, arneses y anclajes (NOM-009-STPS). Safety bonds obligatorios en equipo suspendido.','Strict use of personal fall arrest systems (harness, lifeline) above 1.8m (6ft). Perimeter guardrails. Daily inspection of lifting equipment, harnesses, and anchor points. Mandatory safety bonds on suspended equipment.','B',4,66,1),
  ('CON-013','construction','heights','Vuelco o caída desde plataforma de tijera al montar escenografía alta','Tip-over or fall from scissor lift while installing tall scenery','Plataforma elevadora de tijera usada en piso irregular o sobrecargada para montar escenografía; vuelco o caída del ocupante.','Scissor lift used on uneven floor or overloaded to install scenery; tip-over or occupant fall.','Uso estricto de sistema personal de detención de caídas (arnés, línea de vida) a más de 1.8m. Barandales perimetrales. Inspección diaria de equipos de elevación, arneses y anclajes (NOM-009-STPS). Safety bonds obligatorios en equipo suspendido.','Strict use of personal fall arrest systems (harness, lifeline) above 1.8m (6ft). Perimeter guardrails. Daily inspection of lifting equipment, harnesses, and anchor points. Mandatory safety bonds on suspended equipment.','C',4,67,1),
  ('CON-014','construction','electrical','Distribución eléctrica temporal del taller con cables dañados o sin tierra','Temporary shop electrical distribution with damaged cords or no ground','Extensiones y tableros temporales del taller con aislamiento dañado, empalmes o sin conexión a tierra; riesgo de choque.','Temporary shop extension cords and panels with damaged insulation, splices, or no ground; shock hazard.','Inspección previa por eléctrico calificado. Asegurar conexiones y tableros. Uso de EPP dieléctrico, procedimiento LOTO (NOM-029-STPS), ruteo seguro de cableado, pasacables, y protección diferencial (GFCI/RCD).','Pre-inspection by a qualified electrician. Secure connections/panels. Use of dielectric PPE, LOTO procedure (OSHA), safe cable routing, cable crossovers, and GFCI/RCD protection.','B',4,68,1),
  ('CON-015','construction','electrical','Choque eléctrico por herramienta con cable o carcasa dañada','Electric shock from power tool with damaged cord or housing','Herramienta eléctrica de mano con cable pelado o carcasa rota energizada; el operador recibe una descarga.','Handheld power tool with a frayed cord or cracked energized housing; the operator receives a shock.','Inspección previa por eléctrico calificado. Asegurar conexiones y tableros. Uso de EPP dieléctrico, procedimiento LOTO (NOM-029-STPS), ruteo seguro de cableado, pasacables, y protección diferencial (GFCI/RCD).','Pre-inspection by a qualified electrician. Secure connections/panels. Use of dielectric PPE, LOTO procedure (OSHA), safe cable routing, cable crossovers, and GFCI/RCD protection.','B',3,69,1),
  ('CON-016','construction','hazmat','Vapores tóxicos e inflamables al pintar o lacar sin ventilación','Toxic and flammable vapors when painting or lacquering without ventilation','Aplicación de pintura, laca o solventes en área cerrada sin extracción ni respirador; acumulación de vapores.','Applying paint, lacquer, or solvents in an enclosed area without extraction or respirator; vapor buildup.','Identificación y etiquetado (SGA). Hojas de datos de seguridad (HDS). Uso de EPP específico (respiradores N95/P100, Tyvek). Estaciones de lavado de ojos/duchas. Eliminación adecuada. Fumigación preventiva para biológicos (NOM-018-STPS).','Identification and labeling (GHS). Safety Data Sheets (SDS). Specific PPE (N95/P100 respirators, Tyvek). Eyewash/shower stations. Proper disposal. Preventive fumigation for biologicals.','B',3,70,1),
  ('CON-017','construction','fire','Incendio por almacenamiento de inflamables sin gabinete en el taller','Fire from storing flammables without a cabinet in the shop','Pinturas, solventes y thinner acumulados fuera de gabinete antiflama junto a fuentes de ignición; riesgo de incendio.','Paints, solvents, and thinner stored outside a flammable cabinet near ignition sources; fire risk.','Retirar material combustible de fuentes de ignición. Disponer de extintores PQS/CO2 tipo ABC. Inspección de calentamiento en luces. Designar fire watch en caso de flama abierta (NOM-002-STPS).','Remove combustible materials from ignition sources. Have ABC PQS/CO2 fire extinguishers on hand. Inspect lights for overheating. Assign a fire watch for open flames.','C',4,71,1),
  ('CON-018','construction','health','Lesión lumbar por manejo manual de paneles o escenografía pesada','Back injury from manual handling of heavy panels or scenery','Levantamiento y traslado manual de tableros o piezas de escenografía pesadas sin ayuda mecánica ni técnica adecuada.','Manually lifting and moving heavy panels or scenery pieces without mechanical aid or proper technique.','Evaluación de riesgos en sitio (Risk Assessment) previa. Junta de seguridad (Safety Briefing) obligatoria. Uso de EPP básico. Delimitación y señalización del área de trabajo. Paramédico o primeros auxilios en set.','Prior on-site Risk Assessment. Mandatory Safety Briefing. Basic PPE use. Demarcation and signaling of the work area. Paramedic or first aid on set.','B',3,72,1),
  ('CON-019','construction','structural','Colapso de material estibado (madera o paneles mal apilados)','Collapse of stacked material (poorly piled lumber or panels)','Pilas altas e inestables de madera, tableros o escenografía que se desploman sobre el personal del taller.','Tall, unstable stacks of lumber, panels, or scenery that topple onto shop personnel.','Evaluación estructural por perito (DRO) o ingeniero calificado. Apuntalamiento preventivo. Restricción de carga viva en la zona. Monitoreo constante de vibraciones o asentamientos.','Structural evaluation by a qualified engineer. Preventive shoring. Live load restriction in the area. Constant monitoring of vibrations or settlement.','C',3,73,1),
  ('CON-020','construction','traffic','Atropello o vuelco por montacargas maniobrando material en el taller','Struck-by or tip-over from forklift moving material in the shop','Montacargas o patín motorizado que traslada tableros y estructuras en zona con personal a pie, sin ruta ni señalización.','Forklift or powered pallet jack moving panels and structures where workers walk, with no route or signage.','Cierre total o parcial de calles con autoridades (Policía/Tránsito). Escolta policial. Uso de cinturones/arneses dentro de vehículos. Perímetro de seguridad. Prohibición de viajar en bateas o exterior sin rigging certificado.','Full/partial street closures with local authorities (Police/Traffic). Police escort. Use of seatbelts/harnesses inside vehicles. Safety perimeter. Prohibition of riding in truck beds or exterior without certified rigging.','C',4,74,1),
  ('CON-021','construction','health','Pérdida auditiva por ruido continuo elevado del taller','Hearing loss from sustained high shop noise','Exposición prolongada al ruido de sierras, routers y compresores sin protección auditiva ni control de exposición.','Prolonged exposure to noise from saws, routers, and compressors without hearing protection or exposure control.','Evaluación de riesgos en sitio (Risk Assessment) previa. Junta de seguridad (Safety Briefing) obligatoria. Uso de EPP básico. Delimitación y señalización del área de trabajo. Paramédico o primeros auxilios en set.','Prior on-site Risk Assessment. Mandatory Safety Briefing. Basic PPE use. Demarcation and signaling of the work area. Paramedic or first aid on set.','A',3,75,1),
  ('CON-022','construction','structural','Resbalones, tropiezos y pisadas de clavos por orden y limpieza deficiente','Slips, trips, and nail punctures from poor housekeeping','Piso del taller con cables, recortes, aserrín y clavos sueltos que provocan tropiezos, caídas y heridas punzantes.','Shop floor littered with cords, offcuts, sawdust, and loose nails causing trips, falls, and puncture wounds.','Evaluación estructural por perito (DRO) o ingeniero calificado. Apuntalamiento preventivo. Restricción de carga viva en la zona. Monitoreo constante de vibraciones o asentamientos.','Structural evaluation by a qualified engineer. Preventive shoring. Live load restriction in the area. Constant monitoring of vibrations or settlement.','B',2,76,1),
  ('ENV-001','transversal','weather','Exposición prolongada a radiación UV solar en exteriores',NULL,NULL,NULL,'Carpas o carpas (EZ-ups) obligatorias. Provisión de protector solar SPF50+, sombreros. Descansos en sombra.','Mandatory tents (EZ-ups). Provision of SPF50+ sunscreen, hats. Shade breaks.',NULL,NULL,0,1),
  ('ENV-002','transversal','biological','Picadura de fauna local (alacranes, serpientes, mosquitos - Dengue/Zika)',NULL,NULL,NULL,'Botiquín con antiviperinos/antiarácnidos en sitio. Fumigación preventiva. Repelente con DEET. Botas altas.','On-site antivenom kits. Preventive fumigation. DEET repellent. High boots.',NULL,NULL,0,1),
  ('GEN-001','transversal','health','Fatiga extrema por jornadas >12h o turnos cruzados (Fraturdays)',NULL,NULL,NULL,'Monitoreo de horas. Descanso mínimo 10-12h. Provisión de transporte u hospedaje.','Hours monitoring. Min 10-12h turnaround. Transport or lodging provision.',NULL,NULL,0,1),
  ('GEN-002','transversal','security','Agresión de terceros / Inseguridad pública en locación (Robo a crew)',NULL,NULL,NULL,'Anillos de seguridad perimetral. Enlace con policía local. Transporte en convoy para equipo costoso. Set cerrado.','Perimeter security rings. Local police liaison. Convoy transport for expensive equipment. Closed set.',NULL,NULL,0,1),
  ('GRP-001','transversal','heights','Caída de luces/stands por falta de sacos de arena (sandbags) o safety cables',NULL,NULL,NULL,'Bolsas de arena obligatorias en cada pata de los stands pesados. Cables de seguridad atando el aparato al anclaje.','Mandatory sandbags on each leg of heavy stands. Safety cables securing the fixture to anchor.',NULL,NULL,0,1),
  ('LOC-001','location','heights','Caída desde borde de azotea o cornisa de edificio real sin protección perimetral','Fall from a roof edge or cornice of a real building without perimeter protection','Rodaje en azoteas, balcones o cornisas de edificaciones encontradas sin barandal, red ni línea de vida.','Shooting on rooftops, balconies or cornices of found buildings without guardrail, net or lifeline.','Uso estricto de sistema personal de detención de caídas (arnés, línea de vida) a más de 1.8m. Barandales perimetrales. Inspección diaria de equipos de elevación, arneses y anclajes (NOM-009-STPS). Safety bonds obligatorios en equipo suspendido.','Strict use of personal fall arrest systems (harness, lifeline) above 1.8m (6ft). Perimeter guardrails. Daily inspection of lifting equipment, harnesses, and anchor points. Mandatory safety bonds on suspended equipment.','C',5,1,1),
  ('LOC-002','location','heights','Caída en terreno escarpado o borde de acantilado natural durante desplazamiento del crew','Fall on steep terrain or a natural cliff edge while the crew moves around','Tránsito de personal y equipo por laderas, barrancas o filos de acantilado sin protección de borde.','Crew and gear moving along slopes, ravines or cliff edges without edge protection.','Uso estricto de sistema personal de detención de caídas (arnés, línea de vida) a más de 1.8m. Barandales perimetrales. Inspección diaria de equipos de elevación, arneses y anclajes (NOM-009-STPS). Safety bonds obligatorios en equipo suspendido.','Strict use of personal fall arrest systems (harness, lifeline) above 1.8m (6ft). Perimeter guardrails. Daily inspection of lifting equipment, harnesses, and anchor points. Mandatory safety bonds on suspended equipment.','C',4,2,1),
  ('LOC-003','location','structural','Colapso de entrepiso o piso deteriorado en edificación abandonada encontrada','Collapse of a deteriorated floor or mezzanine in a found abandoned building','Ceder de losas, escaleras o entrepisos podridos u oxidados en inmuebles encontrados sin evaluación estructural.','Rotten or corroded slabs, stairs or mezzanines failing in found premises without a structural assessment.','Evaluación estructural por perito (DRO) o ingeniero calificado. Apuntalamiento preventivo. Restricción de carga viva en la zona. Monitoreo constante de vibraciones o asentamientos.','Structural evaluation by a qualified engineer. Preventive shoring. Live load restriction in the area. Constant monitoring of vibrations or settlement.','C',5,3,1),
  ('LOC-004','location','access','Acceso o egreso único o bloqueado que impide la evacuación o la entrada de ambulancia','Single or blocked access/egress preventing evacuation or ambulance entry','Locación con una sola vía de entrada/salida obstruida por vehículos, portones o terreno que retrasa la respuesta de emergencia.','Location with a single entry/exit obstructed by vehicles, gates or terrain that delays emergency response.','Garantizar al menos dos vías de evacuación libres de obstáculos y bien señalizadas. Validar acceso para ambulancias y vehículos de emergencia; mantener áreas de paso libres de equipo (NOM-002-STPS).','Ensure at least two obstacle-free and well-marked evacuation routes. Validate access for ambulances/emergency vehicles; keep walkways clear of equipment.','C',4,4,1),
  ('LOC-005','location','access','Respuesta médica prolongada en locación remota sin plan de evacuación (MEDEVAC)','Prolonged medical response at a remote location without a MEDEVAC plan','Sitios lejanos sin hospital cercano ni ruta/medio de evacuación definido, elevando la gravedad de cualquier lesión.','Distant sites with no nearby hospital and no defined evacuation route or means, worsening any injury outcome.','Garantizar al menos dos vías de evacuación libres de obstáculos y bien señalizadas. Validar acceso para ambulancias y vehículos de emergencia; mantener áreas de paso libres de equipo (NOM-002-STPS).','Ensure at least two obstacle-free and well-marked evacuation routes. Validate access for ambulances/emergency vehicles; keep walkways clear of equipment.','C',4,5,1),
  ('LOC-006','location','traffic','Atropellamiento de crew filmando junto a vía vehicular activa sin cierre de carril','Crew struck by a vehicle while filming next to a live roadway without a lane closure','Personal trabajando al borde de calles o carreteras abiertas al tránsito sin cierre, señalización ni bandereros.','Crew working at the edge of streets or highways open to traffic without closure, signage or flaggers.','Cierre total o parcial de calles con autoridades (Policía/Tránsito). Escolta policial. Uso de cinturones/arneses dentro de vehículos. Perímetro de seguridad. Prohibición de viajar en bateas o exterior sin rigging certificado.','Full/partial street closures with local authorities (Police/Traffic). Police escort. Use of seatbelts/harnesses inside vehicles. Safety perimeter. Prohibition of riding in truck beds or exterior without certified rigging.','C',5,6,1),
  ('LOC-007','location','water','Ahogamiento en agua abierta (mar, río o lago) desde la orilla o una embarcación','Drowning in open water (sea, river or lake) from the shore or a vessel','Caída o inmersión en cuerpos de agua abiertos sin chaleco, rescatista acuático ni bote de seguridad.','Fall or immersion in open water bodies without a life vest, water safety rescuer or safety boat.','Salvavidas certificados (lifeguards/safety divers) y botes de rescate listos. Uso de PFDs (chalecos salvavidas) para el crew. Monitoreo de calidad de agua, temperatura y corrientes. Equipo eléctrico a distancias seguras y con GFCI.','Certified lifeguards/safety divers and rescue boats ready. Use of PFDs (life jackets) for crew. Monitor water quality, temperature, and currents. Electrical equipment at safe distances with GFCI.','C',5,7,1),
  ('LOC-008','location','water','Hipotermia o arrastre por corriente en agua fría de río o mar','Hypothermia or being swept away by current in cold river or sea water','Exposición a agua fría con corrientes, resacas o rápidos que causan pérdida de fuerza e hipotermia.','Exposure to cold water with currents, rip tides or rapids causing loss of strength and hypothermia.','Salvavidas certificados (lifeguards/safety divers) y botes de rescate listos. Uso de PFDs (chalecos salvavidas) para el crew. Monitoreo de calidad de agua, temperatura y corrientes. Equipo eléctrico a distancias seguras y con GFCI.','Certified lifeguards/safety divers and rescue boats ready. Use of PFDs (life jackets) for crew. Monitor water quality, temperature, and currents. Electrical equipment at safe distances with GFCI.','C',4,8,1),
  ('LOC-009','location','weather','Golpe de calor y deshidratación en locación desértica o exterior caluroso','Heat stroke and dehydration at a desert location or hot exterior','Jornadas prolongadas bajo sol intenso y altas temperaturas sin sombra, hidratación ni ciclos de descanso.','Long days under intense sun and high temperatures without shade, hydration or rest cycles.','Monitoreo meteorológico constante. Plan de acción por tormentas eléctricas (regla 30/30). Proveer refugios climáticos, hidratación, sombra o calefacción. Paro de actividades al aire libre ante clima severo (NOM-015-STPS).','Constant weather monitoring. Lightning action plan (30/30 rule). Provide weather shelters, hydration, shade, or heating. Stop outdoor activities during severe weather.','C',4,9,1),
  ('LOC-010','location','weather','Hipotermia o congelación en locación de frío extremo o alta montaña','Hypothermia or frostbite at an extreme cold or high mountain location','Trabajo prolongado en frío extremo, viento o nieve sin abrigo adecuado ni refugios de calentamiento.','Prolonged work in extreme cold, wind or snow without proper clothing or warming shelters.','Monitoreo meteorológico constante. Plan de acción por tormentas eléctricas (regla 30/30). Proveer refugios climáticos, hidratación, sombra o calefacción. Paro de actividades al aire libre ante clima severo (NOM-015-STPS).','Constant weather monitoring. Lightning action plan (30/30 rule). Provide weather shelters, hydration, shade, or heating. Stop outdoor activities during severe weather.','C',4,10,1),
  ('LOC-011','location','weather','Impacto de rayo durante tormenta eléctrica súbita en exterior expuesto','Lightning strike during a sudden electrical storm at an exposed exterior','Personal en campo abierto, agua o cimas expuestas al desarrollarse una tormenta eléctrica sin plan de resguardo.','Crew in open field, water or exposed summits as an electrical storm develops without a shelter plan.','Monitoreo meteorológico constante. Plan de acción por tormentas eléctricas (regla 30/30). Proveer refugios climáticos, hidratación, sombra o calefacción. Paro de actividades al aire libre ante clima severo (NOM-015-STPS).','Constant weather monitoring. Lightning action plan (30/30 rule). Provide weather shelters, hydration, shade, or heating. Stop outdoor activities during severe weather.','C',5,11,1),
  ('LOC-012','location','biological','Mordedura de serpiente venenosa en locación silvestre o desértica','Venomous snake bite at a wilderness or desert location','Encuentro con víboras o reptiles venenosos entre maleza, rocas o escombros del entorno natural encontrado.','Encounter with vipers or venomous reptiles in brush, rocks or debris of the found natural setting.','Identificación y etiquetado (SGA). Hojas de datos de seguridad (HDS). Uso de EPP específico (respiradores N95/P100, Tyvek). Estaciones de lavado de ojos/duchas. Eliminación adecuada. Fumigación preventiva para biológicos (NOM-018-STPS).','Identification and labeling (GHS). Safety Data Sheets (SDS). Specific PPE (N95/P100 respirators, Tyvek). Eyewash/shower stations. Proper disposal. Preventive fumigation for biologicals.','C',4,12,1),
  ('LOC-013','location','biological','Picadura o enjambre de abejas y avispas, o garrapatas vectoras de enfermedad','Bee or wasp stings/swarm, or disease-carrying ticks','Ataque de enjambres, reacción alérgica anafiláctica o exposición a garrapatas transmisoras de enfermedades.','Swarm attack, anaphylactic allergic reaction or exposure to disease-transmitting ticks.','Identificación y etiquetado (SGA). Hojas de datos de seguridad (HDS). Uso de EPP específico (respiradores N95/P100, Tyvek). Estaciones de lavado de ojos/duchas. Eliminación adecuada. Fumigación preventiva para biológicos (NOM-018-STPS).','Identification and labeling (GHS). Safety Data Sheets (SDS). Specific PPE (N95/P100 respirators, Tyvek). Eyewash/shower stations. Proper disposal. Preventive fumigation for biologicals.','C',3,13,1),
  ('LOC-014','location','biological','Encuentro con fauna silvestre mayor (oso, felino o jabalí) en locación remota','Encounter with large wildlife (bear, big cat or wild boar) at a remote location','Aproximación de fauna mayor atraída por comida o desechos de producción en sitios silvestres o remotos.','Large wildlife approaching, drawn by food or production waste at wilderness or remote sites.','Identificación y etiquetado (SGA). Hojas de datos de seguridad (HDS). Uso de EPP específico (respiradores N95/P100, Tyvek). Estaciones de lavado de ojos/duchas. Eliminación adecuada. Fumigación preventiva para biológicos (NOM-018-STPS).','Identification and labeling (GHS). Safety Data Sheets (SDS). Specific PPE (N95/P100 respirators, Tyvek). Eyewash/shower stations. Proper disposal. Preventive fumigation for biologicals.','D',4,14,1),
  ('LOC-015','location','biological','Dermatitis por contacto con plantas venenosas (hiedra o roble venenoso, ortiga)','Dermatitis from contact with poisonous plants (poison ivy/oak, nettle)','Contacto con vegetación urticante o tóxica del entorno que provoca dermatitis o reacción alérgica.','Contact with stinging or toxic vegetation in the environment causing dermatitis or allergic reaction.','Identificación y etiquetado (SGA). Hojas de datos de seguridad (HDS). Uso de EPP específico (respiradores N95/P100, Tyvek). Estaciones de lavado de ojos/duchas. Eliminación adecuada. Fumigación preventiva para biológicos (NOM-018-STPS).','Identification and labeling (GHS). Safety Data Sheets (SDS). Specific PPE (N95/P100 respirators, Tyvek). Eyewash/shower stations. Proper disposal. Preventive fumigation for biologicals.','C',2,15,1),
  ('LOC-016','location','hazmat','Exposición a humo de incendio forestal o mala calidad del aire en exteriores','Exposure to wildfire smoke or poor outdoor air quality','Rodaje bajo humo de incendios cercanos o alta contaminación del aire sin monitoreo de AQI ni protección respiratoria.','Shooting under smoke from nearby fires or high air pollution without AQI monitoring or respiratory protection.','Uso exclusivo de fluidos aprobados (agua/glicerina). Ventilación mecánica periódica del set. Monitoreo de calidad del aire. EPP respiratorio opcional para crew; descansos fuera del ambiente cargado.','Exclusive use of approved fluids (water/glycerin). Periodic mechanical ventilation of the set. Air quality monitoring. Optional respiratory PPE for crew; breaks outside the foggy environment.','C',3,16,1),
  ('LOC-017','location','hazmat','Exposición a asbesto o plomo en edificación antigua encontrada','Exposure to asbestos or lead in a found old building','Perturbación de recubrimientos, pintura o aislantes con asbesto o plomo en inmuebles viejos usados como locación.','Disturbing coatings, paint or insulation containing asbestos or lead in old premises used as a location.','Identificación y etiquetado (SGA). Hojas de datos de seguridad (HDS). Uso de EPP específico (respiradores N95/P100, Tyvek). Estaciones de lavado de ojos/duchas. Eliminación adecuada. Fumigación preventiva para biológicos (NOM-018-STPS).','Identification and labeling (GHS). Safety Data Sheets (SDS). Specific PPE (N95/P100 respirators, Tyvek). Eyewash/shower stations. Proper disposal. Preventive fumigation for biologicals.','C',4,17,1),
  ('LOC-018','location','hazmat','Inhalación de esporas de moho o guano (histoplasmosis) en interior abandonado','Inhalation of mold spores or bat/bird guano (histoplasmosis) in an abandoned interior','Interiores húmedos o con acumulación de excremento de aves/murciélagos que liberan esporas patógenas al removerlos.','Damp interiors or bird/bat droppings that release pathogenic spores when disturbed.','Identificación y etiquetado (SGA). Hojas de datos de seguridad (HDS). Uso de EPP específico (respiradores N95/P100, Tyvek). Estaciones de lavado de ojos/duchas. Eliminación adecuada. Fumigación preventiva para biológicos (NOM-018-STPS).','Identification and labeling (GHS). Safety Data Sheets (SDS). Specific PPE (N95/P100 respirators, Tyvek). Eyewash/shower stations. Proper disposal. Preventive fumigation for biologicals.','C',3,18,1),
  ('LOC-019','location','hazmat','Inhalación de polvo de sílice en caminos de terracería o desierto','Inhalation of respirable silica dust on dirt roads or desert','Polvo levantado por vehículos, viento o pisado del crew en terracería/desierto con sílice cristalina respirable.','Dust raised by vehicles, wind or crew foot traffic on dirt/desert carrying respirable crystalline silica.','Identificación y etiquetado (SGA). Hojas de datos de seguridad (HDS). Uso de EPP específico (respiradores N95/P100, Tyvek). Estaciones de lavado de ojos/duchas. Eliminación adecuada. Fumigación preventiva para biológicos (NOM-018-STPS).','Identification and labeling (GHS). Safety Data Sheets (SDS). Specific PPE (N95/P100 respirators, Tyvek). Eyewash/shower stations. Proper disposal. Preventive fumigation for biologicals.','C',3,19,1),
  ('LOC-020','location','confined','Ingreso a sótano, túnel o cisterna encontrada sin monitoreo de atmósfera peligrosa','Entry into a found basement, tunnel or cistern without hazardous atmosphere monitoring','Acceso a espacios confinados del sitio (bodegas, alcantarillas, tanques) sin medición de oxígeno ni gases tóxicos.','Entering the site confined spaces (vaults, sewers, tanks) without oxygen or toxic gas measurement.','Permiso de entrada a espacios confinados. Monitoreo de gases (O2, CO, LEL, H2S). Ventilación mecánica exhaustiva. Vigía (Hole watch) permanente en el exterior. Plan de rescate y arnés de extracción (NOM-033-STPS).','Confined space entry permit. Gas monitoring (O2, CO, LEL, H2S). Exhaustive mechanical ventilation. Permanent Hole Watch outside. Rescue plan and extraction harness.','C',5,20,1),
  ('LOC-021','location','confined','Intoxicación por monóxido de carbono o gases acumulados en interior cerrado','Carbon monoxide or accumulated gas poisoning in an enclosed interior','Acumulación de CO o gases por generadores, motores o escapes cercanos en interiores reales sin ventilación.','CO or gas buildup from nearby generators, engines or exhaust in unventilated real interiors.','Permiso de entrada a espacios confinados. Monitoreo de gases (O2, CO, LEL, H2S). Ventilación mecánica exhaustiva. Vigía (Hole watch) permanente en el exterior. Plan de rescate y arnés de extracción (NOM-033-STPS).','Confined space entry permit. Gas monitoring (O2, CO, LEL, H2S). Exhaustive mechanical ventilation. Permanent Hole Watch outside. Rescue plan and extraction harness.','C',4,21,1),
  ('LOC-022','location','electrical','Contacto con cableado energizado o deteriorado en edificación real encontrada','Contact with energized or deteriorated wiring in a found real building','Instalaciones eléctricas existentes sin identificar, sin corte ni candadeo, con cables expuestos u obsoletos.','Existing electrical installations unidentified, without de-energization or lockout, with exposed or obsolete wiring.','Inspección previa por eléctrico calificado. Asegurar conexiones y tableros. Uso de EPP dieléctrico, procedimiento LOTO (NOM-029-STPS), ruteo seguro de cableado, pasacables, y protección diferencial (GFCI/RCD).','Pre-inspection by a qualified electrician. Secure connections/panels. Use of dielectric PPE, LOTO procedure (OSHA), safe cable routing, cable crossovers, and GFCI/RCD protection.','C',4,22,1),
  ('LOC-023','location','electrical','Contacto con líneas eléctricas aéreas al maniobrar equipo alto en exterior','Contact with overhead power lines while maneuvering tall equipment outdoors','Grúas, plumas, mástiles o escaleras que se aproximan a líneas de distribución aéreas en la locación exterior.','Cranes, booms, masts or ladders approaching overhead distribution lines at the exterior location.','Inspección previa por eléctrico calificado. Asegurar conexiones y tableros. Uso de EPP dieléctrico, procedimiento LOTO (NOM-029-STPS), ruteo seguro de cableado, pasacables, y protección diferencial (GFCI/RCD).','Pre-inspection by a qualified electrician. Secure connections/panels. Use of dielectric PPE, LOTO procedure (OSHA), safe cable routing, cable crossovers, and GFCI/RCD protection.','C',5,23,1),
  ('LOC-024','location','fire','Ignición de vegetación seca en exterior sin acceso a agua ni hidrantes','Ignition of dry vegetation outdoors without access to water or hydrants','Fuente de calor, colilla o falla eléctrica que enciende pasto o matorral seco en locación remota sin medios de extinción.','Heat source, cigarette or electrical fault igniting dry grass or brush at a remote site with no suppression means.','Retirar material combustible de fuentes de ignición. Disponer de extintores PQS/CO2 tipo ABC. Inspección de calentamiento en luces. Designar fire watch en caso de flama abierta (NOM-002-STPS).','Remove combustible materials from ignition sources. Have ABC PQS/CO2 fire extinguishers on hand. Inspect lights for overheating. Assign a fire watch for open flames.','C',4,24,1),
  ('LOC-025','location','crowd','Aglomeración de público o curiosos sin control de multitudes en locación urbana','Bystander or public crowding without crowd control at an urban location','Curiosos, transeúntes o fans invadiendo el perímetro de rodaje en la vía pública sin barreras ni seguridad suficiente.','Onlookers, passersby or fans invading the shooting perimeter on public streets without barriers or enough security.','Control de multitudes con personal de seguridad y barricadas (mojo barriers). Plan de flujo y evacuación de extras. Hidratación y áreas de descanso para figurantes. Puestos médicos avanzados o paramédico dedicado.','Crowd control with security personnel and barricades. Extras flow and evacuation plan. Hydration and rest areas for background talent. Advanced First Aid stations or dedicated paramedic.','C',3,25,1),
  ('LOC-026','location','special','Traslado de crew en vehículos off-road a locación remota por caminos peligrosos','Crew transport in off-road vehicles to a remote location over hazardous roads','Volcadura o accidente de vehículos utilitarios/todo terreno en brechas, vados o pendientes al acceder a sitios remotos.','Rollover or crash of utility/off-road vehicles on trails, fords or slopes while accessing remote sites.','Manejo exclusivo por técnico de FX/Pirotecnia con licencia. Almacenamiento aislado. Distancias de separación y barreras de Lexan/acrílico. Extintores cargados, junta de seguridad, simulacro (Dry run). Uso de algodón/Nomex.','Exclusive handling by licensed FX/Pyrotechnic technician. Isolated storage. Safe separation distances and Lexan/acrylic barriers. Charged extinguishers, safety briefing, dry runs. Cotton/Nomex clothing.','C',4,26,1),
  ('LOC-027','location','stunts_vehicular','Persecución / precision driving en vía real o carril cerrado','Chase / precision driving on a live or closed roadway',NULL,NULL,'Cierre total o parcial de calles con autoridades (Policía/Tránsito). Escolta policial. Uso de cinturones/arneses dentro de vehículos. Perímetro de seguridad. Prohibición de viajar en bateas o exterior sin rigging certificado.','Full/partial street closures with local authorities (Police/Traffic). Police escort. Use of seatbelts/harnesses inside vehicles. Safety perimeter. Prohibition of riding in truck beds or exterior without certified rigging.','C',5,905,1),
  ('LOC-028','location','stunts_vehicular','Picture car a velocidad con actor conduciendo (free driving)','Picture car at speed with actor driving',NULL,NULL,'Cierre total o parcial de calles con autoridades (Policía/Tránsito). Escolta policial. Uso de cinturones/arneses dentro de vehículos. Perímetro de seguridad. Prohibición de viajar en bateas o exterior sin rigging certificado.','Full/partial street closures with local authorities (Police/Traffic). Police escort. Use of seatbelts/harnesses inside vehicles. Safety perimeter. Prohibition of riding in truck beds or exterior without certified rigging.','C',4,906,1),
  ('LOC-029','location','stunts_high_fall','High fall desde estructura o acantilado real a sistema de recepción','High fall from a real structure or cliff onto a catch system',NULL,NULL,'Coreografía por Stunt Coordinator. Ensayos a media velocidad (\'walk-throughs\'). Uso de tapetes de caída (crash pads), protección corporal oculta. Personal médico en standby. Autoridad del Stunt Coordinator para abortar la toma.','Choreography by Stunt Coordinator. Half-speed rehearsals (\'walk-throughs\'). Use of crash pads, hidden body protection. Medical personnel on standby. Stunt Coordinator has authority to abort the take.','D',5,910,1),
  ('LOC-030','location','railroad','Filmación en o junto a vía férrea activa sin control de tren','Filming on/beside a live railroad track without train control',NULL,NULL,'Evaluación de riesgos en sitio (Risk Assessment) previa. Junta de seguridad (Safety Briefing) obligatoria. Uso de EPP básico. Delimitación y señalización del área de trabajo. Paramédico o primeros auxilios en set.','Prior on-site Risk Assessment. Mandatory Safety Briefing. Basic PPE use. Demarcation and signaling of the work area. Paramedic or first aid on set.','D',5,928,1),
  ('LOC-031','location','uncontrolled_env','Grabación de reality/documental en operación policial, disturbio o zona de riesgo real','Reality/doc shooting during a police op, riot or real danger zone',NULL,NULL,'Identificación y etiquetado (SGA). Hojas de datos de seguridad (HDS). Uso de EPP específico (respiradores N95/P100, Tyvek). Estaciones de lavado de ojos/duchas. Eliminación adecuada. Fumigación preventiva para biológicos (NOM-018-STPS).','Identification and labeling (GHS). Safety Data Sheets (SDS). Specific PPE (N95/P100 respirators, Tyvek). Eyewash/shower stations. Proper disposal. Preventive fumigation for biologicals.','C',5,930,1),
  ('LOC-032','location','utility_transport','Accidente de van o vehículo de crew en traslado a/desde la locación','Crew van/vehicle accident in transit',NULL,NULL,'Evaluación de riesgos en sitio (Risk Assessment) previa. Junta de seguridad (Safety Briefing) obligatoria. Uso de EPP básico. Delimitación y señalización del área de trabajo. Paramédico o primeros auxilios en set.','Prior on-site Risk Assessment. Mandatory Safety Briefing. Basic PPE use. Demarcation and signaling of the work area. Paramedic or first aid on set.','C',5,980,1),
  ('LOC-033','location','utility_transport','Conducción de crew con fatiga tras jornada larga (turnaround insuficiente)','Fatigued crew driving after a long day',NULL,NULL,'Monitoreo de horas de trabajo. Descanso mínimo de 10-12 horas (Turnaround). Transporte provisto por la producción para cansancio extremo. Pausas activas.','Working hours monitoring. Minimum 10-12 hours turnaround time. Production-provided transport for extreme fatigue. Active breaks.','C',5,981,1),
  ('LOC-034','location','base_camp','Riesgos en campamento base (tránsito interno, generadores, catering, EPP)','Base camp hazards (internal traffic, generators, catering, PPE)',NULL,NULL,'Evaluación de riesgos en sitio (Risk Assessment) previa. Junta de seguridad (Safety Briefing) obligatoria. Uso de EPP básico. Delimitación y señalización del área de trabajo. Paramédico o primeros auxilios en set.','Prior on-site Risk Assessment. Mandatory Safety Briefing. Basic PPE use. Demarcation and signaling of the work area. Paramedic or first aid on set.','B',3,985,1),
  ('LOC-035','location','weather','Suspensión por rayos o clima severo en locación (lightning hold)','Lightning or severe-weather hold at location',NULL,NULL,'Monitoreo meteorológico constante. Plan de acción por tormentas eléctricas (regla 30/30). Proveer refugios climáticos, hidratación, sombra o calefacción. Paro de actividades al aire libre ante clima severo (NOM-015-STPS).','Constant weather monitoring. Lightning action plan (30/30 rule). Provide weather shelters, hydration, shade, or heating. Stop outdoor activities during severe weather.','C',4,986,1),
  ('LOC-036','location','traffic','Riesgos por set no asegurado (lockup) y peatones entrando a la zona de acción',NULL,NULL,NULL,'Uso de PAs (Asistentes de Producción) para lockups efectivos. Cintas de barricada. Policías de tránsito.','Use of PAs for effective lockups. Barricade tape. Traffic police.',NULL,NULL,0,1),
  ('LOC-037','location','hazmat','Manejo inadecuado de cilindros de gas L.P. en camper de maquillaje o catering',NULL,NULL,NULL,'Cilindros asegurados en posición vertical a estructura fija (cadenas). Lejos de fuentes de ignición. Válvulas protegidas.','Cylinders secured upright to fixed structure (chains). Away from ignition sources. Protected valves.',NULL,NULL,0,1),
  ('LOC-038','location','health','Falta de comunicación (radios sin señal) en locaciones remotas de montaña',NULL,NULL,NULL,'Teléfonos satelitales obligatorios para el Medic/Seguridad. Repetidoras de radio instaladas. Acordar puntos de reunión.','Mandatory satellite phones for Medic/Safety. Installed radio repeaters. Agreed assembly points.',NULL,NULL,0,1),
  ('SET-001','film_set','heights','Trabajo en altura en parrilla sin protección contra caídas','Work at height on the lighting grid without fall protection','Montaje de luminarias y truss en la parrilla del foro sin arnés ni línea de vida.','Rigging lights and truss on the stage grid without a harness or lifeline.','Uso estricto de sistema personal de detención de caídas (arnés, línea de vida) a más de 1.8m. Barandales perimetrales. Inspección diaria de equipos de elevación, arneses y anclajes (NOM-009-STPS). Safety bonds obligatorios en equipo suspendido.','Strict use of personal fall arrest systems (harness, lifeline) above 1.8m (6ft). Perimeter guardrails. Daily inspection of lifting equipment, harnesses, and anchor points. Mandatory safety bonds on suspended equipment.','C',5,27,1),
  ('SET-002','film_set','heights','Caída desde plataforma elevadora (condor / scissor lift) mal estabilizada','Fall from an unstable aerial work platform (condor / scissor lift)','Ajuste de iluminación desde boom/scissor lift movida con el operador arriba o sin estabilizadores.','Adjusting lights from a boom/scissor lift moved while the operator is aloft or without outriggers.','Uso estricto de sistema personal de detención de caídas (arnés, línea de vida) a más de 1.8m. Barandales perimetrales. Inspección diaria de equipos de elevación, arneses y anclajes (NOM-009-STPS). Safety bonds obligatorios en equipo suspendido.','Strict use of personal fall arrest systems (harness, lifeline) above 1.8m (6ft). Perimeter guardrails. Daily inspection of lifting equipment, harnesses, and anchor points. Mandatory safety bonds on suspended equipment.','C',5,28,1),
  ('SET-003','film_set','heights','Caída desde parallel / riser de cámara sin barandal','Fall from a camera parallel / riser without guardrail','Operación de cámara sobre parallels o risers elevados sin barandal ni rodapié perimetral.','Operating camera on elevated parallels or risers with no guardrail or toe-board.','Uso estricto de sistema personal de detención de caídas (arnés, línea de vida) a más de 1.8m. Barandales perimetrales. Inspección diaria de equipos de elevación, arneses y anclajes (NOM-009-STPS). Safety bonds obligatorios en equipo suspendido.','Strict use of personal fall arrest systems (harness, lifeline) above 1.8m (6ft). Perimeter guardrails. Daily inspection of lifting equipment, harnesses, and anchor points. Mandatory safety bonds on suspended equipment.','C',4,29,1),
  ('SET-004','film_set','heights','Golpe por objeto o herramienta que cae desde la parrilla','Struck by a tool or object dropped from the grid','Herramienta, tornillería o accesorio no amarrado cae desde altura sobre el personal en piso.','An untethered tool, hardware, or accessory falls from height onto crew below.','Uso estricto de sistema personal de detención de caídas (arnés, línea de vida) a más de 1.8m. Barandales perimetrales. Inspección diaria de equipos de elevación, arneses y anclajes (NOM-009-STPS). Safety bonds obligatorios en equipo suspendido.','Strict use of personal fall arrest systems (harness, lifeline) above 1.8m (6ft). Perimeter guardrails. Daily inspection of lifting equipment, harnesses, and anchor points. Mandatory safety bonds on suspended equipment.','C',4,30,1),
  ('SET-005','film_set','electrical','Contacto con distribución eléctrica temporal mojada','Contact with wet temporary electrical distribution','Cables de fuerza, distros y conexiones portátiles en contacto con agua o piso mojado del set.','Feeder cables, distros, and portable connections in contact with water or a wet set floor.','Inspección previa por eléctrico calificado. Asegurar conexiones y tableros. Uso de EPP dieléctrico, procedimiento LOTO (NOM-029-STPS), ruteo seguro de cableado, pasacables, y protección diferencial (GFCI/RCD).','Pre-inspection by a qualified electrician. Secure connections/panels. Use of dielectric PPE, LOTO procedure (OSHA), safe cable routing, cable crossovers, and GFCI/RCD protection.','C',5,31,1),
  ('SET-006','film_set','electrical','Mantenimiento de luminaria energizada sin bloqueo (LOTO)','Servicing an energized fixture without lockout (LOTO)','Cambio de lámpara o reparación de una luminaria/distro sin des-energizar ni bloquear la fuente.','Relamping or repairing a fixture/distro without de-energizing and locking out the source.','Inspección previa por eléctrico calificado. Asegurar conexiones y tableros. Uso de EPP dieléctrico, procedimiento LOTO (NOM-029-STPS), ruteo seguro de cableado, pasacables, y protección diferencial (GFCI/RCD).','Pre-inspection by a qualified electrician. Secure connections/panels. Use of dielectric PPE, LOTO procedure (OSHA), safe cable routing, cable crossovers, and GFCI/RCD protection.','C',4,32,1),
  ('SET-007','film_set','access','Tropiezo por tendido de cables en pasillos y accesos','Trip hazard from cable runs across walkways and accesses','Cableado de fuerza y video cruzando pasillos, accesos y rutas de egreso sin canaletas ni protección.','Power and video cabling crossing walkways, accesses, and egress routes without ramps or covers.','Garantizar al menos dos vías de evacuación libres de obstáculos y bien señalizadas. Validar acceso para ambulancias y vehículos de emergencia; mantener áreas de paso libres de equipo (NOM-002-STPS).','Ensure at least two obstacle-free and well-marked evacuation routes. Validate access for ambulances/emergency vehicles; keep walkways clear of equipment.','B',2,33,1),
  ('SET-008','film_set','access','Salidas de emergencia obstruidas por equipo o set pieces','Emergency exits blocked by gear or set pieces','Rutas de evacuación y extintores bloqueados por carros, cajas de grip o piezas del set durante el rodaje.','Evacuation routes and extinguishers blocked by carts, grip cases, or set pieces during the shoot.','Garantizar al menos dos vías de evacuación libres de obstáculos y bien señalizadas. Validar acceso para ambulancias y vehículos de emergencia; mantener áreas de paso libres de equipo (NOM-002-STPS).','Ensure at least two obstacle-free and well-marked evacuation routes. Validate access for ambulances/emergency vehicles; keep walkways clear of equipment.','C',4,34,1),
  ('SET-009','film_set','fire','Luminaria caliente que enciende telones o vestido del set','Hot fixture igniting drapes or set dressing','Fixture o HMI muy caliente demasiado cerca de cortinas, gasa o vestido inflamable del set.','A hot fixture or HMI placed too close to curtains, gauze, or flammable set dressing.','Retirar material combustible de fuentes de ignición. Disponer de extintores PQS/CO2 tipo ABC. Inspección de calentamiento en luces. Designar fire watch en caso de flama abierta (NOM-002-STPS).','Remove combustible materials from ignition sources. Have ABC PQS/CO2 fire extinguishers on hand. Inspect lights for overheating. Assign a fire watch for open flames.','C',4,35,1),
  ('SET-010','film_set','fire','Efecto de fuego abierto en escena (velas, antorchas, gas)','Open-flame practical effect on set (candles, torches, gas)','Práctico de flama viva en cuadro sin extintor dedicado, pantalla ni personal de bomberos de set.','A live-flame practical on camera without a dedicated extinguisher, screen, or set fire safety officer.','Extintores y mantas ignífugas a menos de 5m. Designar Guardia de fuego (Fire watch). Tratamiento ignífugo a sets/vestuario. Ensayo previo y junta de seguridad. EPP Nomex/ignífugo para talento y crew cercano (NOM-002-STPS).','Extinguishers and fire blankets within 5m. Designate Fire Watch. Fire retardant treatment for sets/wardrobe. Pre-rehearsal and safety briefing. Nomex/fire-retardant PPE for talent and nearby crew.','C',4,36,1),
